def calculate_incarnation_cross(
    pers_sun_line: int,
    design_sun_line: int,
    pers_sun_gate: int,
    design_sun_gate: int,
    pers_earth_gate: int,
    design_earth_gate: int,
) -> str:
    """Name the cross, e.g. "Right Angle Cross of Penetration 2 (53/54 | 51/57)".

    Format: (Personality Sun / Personality Earth | Design Sun / Design Earth).
    """
    gates = f"({pers_sun_gate}/{pers_earth_gate} | {design_sun_gate}/{design_earth_gate})"
    if pers_sun_line < 5 and design_sun_line >= 3:
        cross_name = RIGHT_ANGLE_CROSSES.get(pers_sun_gate, f"Unknown Gate {pers_sun_gate}")
        return f"Right Angle Cross of {cross_name} {gates}"
    if pers_sun_line >= 5:
        cross_name = LEFT_ANGLE_CROSSES.get(pers_sun_gate, f"Unknown Gate {pers_sun_gate}")
        return f"Left Angle Cross of {cross_name} {gates}"
    cross_name = JUXTAPOSITION_CROSSES.get(pers_sun_gate, f"Unknown Gate {pers_sun_gate}")
    return f"Juxtaposition Cross of {cross_name} {gates}"
